package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {







    @Test
    public void testCreateNumber_Hex() throws NumberFormatException {
        // Testing 0x and -0x logic via createInteger
        Number res = NumberUtils.createNumber("0x10");
        assertTrue(res instanceof Integer);
        assertEquals(16, res.intValue());

        Number resNeg = NumberUtils.createNumber("-0x10");
        assertTrue(resNeg instanceof Integer);
        assertEquals(-16, resNeg.intValue());
    }




















}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {









    @Test
    public void testCreateNumber_IntegerTypes() throws NumberFormatException {
        // Integer
        Number n1 = NumberUtils.createNumber("123");
        assertTrue(n1 instanceof Integer);
        assertEquals(123, n1.intValue());

        // Long
        Number n2 = NumberUtils.createNumber("1234567890123");
        assertTrue(n2 instanceof Long);
        assertEquals(1234567890123L, n2.longValue());

        // BigInteger
        Number n3 = NumberUtils.createNumber("9223372036854775808"); // Long.MAX_VALUE + 1
        assertTrue(n3 instanceof BigInteger);
    }


















}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {











    @Test
    public void testCreateNumber_FloatingPointTypes() throws NumberFormatException {
        // Float
        Number f1 = NumberUtils.createNumber("1.23f");
        assertTrue(f1 instanceof Float);
        assertEquals(1.23f, f1.floatValue(), 0.001f);

        // Double
        Number d1 = NumberUtils.createNumber("1.23d");
        assertTrue(d1 instanceof Double);
        assertEquals(1.23, d1.doubleValue(), 0.001);

        // BigDecimal
        Number bd1 = NumberUtils.createNumber("1.234567890123456789");
        assertTrue(bd1 instanceof BigDecimal);
    }
















}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {













    @Test
    public void testCreateNumber_Suffixes() throws NumberFormatException {
        // Long suffix L
        Number l = NumberUtils.createNumber("123L");
        assertTrue(l instanceof Long);
        assertEquals(123L, l.longValue());

        // BigInteger via L (too big for long)
        Number bi = NumberUtils.createNumber("9223372036854775808L");
        assertTrue(bi instanceof BigInteger);

        // Float suffix F
        Number fl = NumberUtils.createNumber("123.45F");
        assertTrue(fl instanceof Float);

        // Double suffix D
        Number dl = NumberUtils.createNumber("123.45D");
        assertTrue(dl instanceof Double);
    }














}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {















    @Test
    public void testCreateNumber_ScientificNotation() throws NumberFormatException {
        // Scientific with decimal
        Number n1 = NumberUtils.createNumber("1.23e2");
        // result is 123.0 -> Double or Float or BigDecimal. 
        // Based on code path: decPos > -1, expPos > -1.
        assertTrue(n1 instanceof Double || n1 instanceof Float || n1 instanceof BigDecimal);

        // Scientific without decimal
        Number n2 = NumberUtils.createNumber("1e2");
        assertTrue(n2 instanceof Integer || n2 instanceof Long || n2 instanceof BigInteger);
    }












}

