public class NumberUtils_createNumber_TriageGen2Test {





















    @Test
    public void testCreateNumber_EdgeCasePrecision() throws NumberFormatException {
        // Test the "allZeros" logic for precision fallback
        // If float value is 0.0 and not all zeros (e.g. 0.00000000000000000000001), it should fall through
        String tiny = "0.00000000000000000000000000000000001";
        Number n = NumberUtils.createNumber(tiny);
        assertTrue(n instanceof BigDecimal);
    }






